 public static void Apply(Window window,TabControl tabs,string subtitle){
  window.Resources.MergedDictionaries.Add(Resources());window.Background=new SolidColorBrush(Color.FromRgb(243,245,248));window.Foreground=Ink;window.FontFamily=new FontFamily("Microsoft YaHei UI");window.FontSize=13;window.Width=1040;window.Height=780;window.MinWidth=930;window.MinHeight=680;window.UseLayoutRounding=true;
  var root=new DockPanel();var header=new Border{Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(225,231,237)),BorderThickness=new Thickness(0,0,0,1),Padding=new Thickness(26,13,26,13)};DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
  var line=new DockPanel();header.Child=line;var badge=new TextBlock{Text="LOCAL  /  V3",Foreground=new SolidColorBrush(Color.FromRgb(181,57,71)),FontSize=11,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(15,0,0,0)};DockPanel.SetDock(badge,Dock.Right);line.Children.Add(badge);
  string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"conan.png");if(File.Exists(path)){var image=new BitmapImage(new Uri(path));var avatar=new Image{Source=new CroppedBitmap(image,new Int32Rect(0,0,192,208)),Width=46,Height=50,Margin=new Thickness(0,0,14,0)};DockPanel.SetDock(avatar,Dock.Left);line.Children.Add(avatar);}
  var searchPanel=new StackPanel{Width=190,Margin=new Thickness(20,0,10,0),VerticalAlignment=VerticalAlignment.Center};DockPanel.SetDock(searchPanel,Dock.Right);line.Children.Add(searchPanel);var search=new TextBox{ToolTip="输入页面名称后按Enter跳转",MinHeight=30,Padding=new Thickness(7,4,7,4)};System.Windows.Automation.AutomationProperties.SetName(search,"搜索技能");searchPanel.Children.Add(search);var searchHint=new TextBlock{Text="搜索技能 · Enter跳转",Foreground=Brushes.SlateGray,FontSize=10,Margin=new Thickness(1,3,0,0)};searchPanel.Children.Add(searchHint);search.KeyDown+=(s,e)=>{if(e.Key!=System.Windows.Input.Key.Enter)return;string query=search.Text.Trim();if(query.Length==0)return;foreach(TabItem tab in tabs.Items)if(Convert.ToString(tab.Header).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0){tabs.SelectedItem=tab;searchHint.Text="已打开："+tab.Header;e.Handled=true;return;}searchHint.Text="没有匹配的页面";e.Handled=true;};
  var title=new StackPanel{VerticalAlignment=VerticalAlignment.Center};title.Children.Add(new TextBlock{Text="柯南 · 侦探工作台",FontSize=22,FontWeight=FontWeights.SemiBold});title.Children.Add(new TextBlock{Text=subtitle,Foreground=Brushes.SlateGray,FontSize=12,Margin=new Thickness(0,3,0,0)});line.Children.Add(title);
  tabs.Margin=new Thickness(0);root.Children.Add(tabs);window.Content=root;
 }
 public static void PageHeading(Panel panel,string name,string caption){panel.Children.Add(new TextBlock{Text=name,FontSize=25,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,6),Foreground=Ink});if(!String.IsNullOrEmpty(caption))panel.Children.Add(new TextBlock{Text=caption,Foreground=Brushes.SlateGray,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,21)});}
}
